package Koha::Plugin::Com::JunaidZaidiLibrary::DigitalCirculation::Controller::Health; use Mojo::Base 'Mojolicious::Controller'; use Mojo::JSON qw(true false); use C4::Context; use Koha; use Koha::Plugin::Com::JunaidZaidiLibrary::DigitalCirculation;
sub health{my($c)=@_;my$db=eval{C4::Context->dbh->selectrow_array('SELECT 1')};my$ok=$db?true:false;return$c->render(status=>$db?200:503,json=>{loaded=>true,plugin_version=>'0.2.0',schema_version=>1,database=>$ok?'available':'unavailable',koha_compatible=>Koha->VERSION=~/\A26\.05\./?true:false,read_only=>false,current_utc=>scalar gmtime().'Z'})}
sub version{shift->render(json=>{plugin_version=>'0.2.0',tested_koha_version=>'26.05.01.000',minimum_koha_version=>'26.05.00.000',schema_version=>1,api_version=>'v1',phase=>'2A',read_only=>false})} 1;
